function landmarkKey(raw){
  let k=String(raw||'').toUpperCase();
  k=k.replace(/\(MRHFL\)|\(SADAR EARLIER\)|\(UP\)|\(RAJASTHAN\)|\(ALLAHABAD\)|\(LCK\)/g,'');
  k=k.replace(/-\s*(LCK|CDG|CV|PUNJAB|RAJASTHAN|U\.P\.?)/g,'');
  k=k.replace(/\/\s*(JODHPUR RO|TRANSPORT NAGAR BRANCH)/g,'');
  k=k.replace(/\b(RO|CV|TWO|SB)\b/g,'');
  k=k.replace(/\s+/g,' ').trim();
  const aliases=[
    ['ALLAHABAD','ALLAHABAD'],['PRAYAGRAJ','PRAYAGRAJ'],['AZAMGARH','AZAMGARH LCK'],['GHAZIPUR-UP','GHAZIPUR'],
    ['GONDA (UP)','GONDA'],['GORAKHPUR (UP)','GORAKHPUR'],['HAMIRPUR UP','HAMIRPUR'],['HARDOI-UP','HARDOI'],
    ['JOUNPUR','JOUNPUR'],['JHANSI','JHANSI'],['LAKHIMPUR-KHERI','LAKHIMPUR-KHERI'],['MIRZAPUR - LCK','MIRZAPUR'],
    ['SULTANPUR-UP','SULTANPUR'],['SITAPUR(KANPUR)','SITAPUR'],['SONEBHADRA','SONEBHADRA'],['VARANASI - LCK','VARANASI'],
    ['RAI BAREILLY-UP','RAI BAREILLY'],['PRATAPGARH (ALLAHABAD)','PRATAPGARH'],['BAREILLY - LUCKNOW','BAREILLY'],
    ['FAIZABAD - LUCKNOW','FAIZABAD'],['FATEHPUR - KANPUR','FATEHPUR'],['BANDA (ALLAHABAD)','BANDA'],['BALLIA (VARANASI)','BALLIA'],
    ['BALRAMPUR (UP)','BALRAMPUR'],['DEORIA (UP)','DEORIA'],['ETA(UP)','ETAH'],['ETAWAH - LCK','ETAWAH'],
    ['MAU (VARANASI)','MAU'],['MEERUT RO','MEERUT'],['KOTA TWO','KOTA'],['UDAIPUR RO','UDAIPUR'],['JAIPUR RO','JAIPUR'],
    ['JAIPUR TWO/ TRANSPORT NAGAR BRANCH','JAIPUR'],['KARUALI','KARUALI'],['JODHPUR/JODHPUR RO','JODHPUR'],['JHUNJHUNU - RAJASTHAN','JHUNJHUNU'],
    ['SAWAI MADHOPUR-RAJASTHAN','SAWAI MADHOPUR'],['CHURU-RAJASTHAN','CHURU'],['RAJASTHAN','RAJASTHAN'],
    ['HISSAR','HISAR'],['HISSAR CV','HISAR'],['HISAR (LOHARU)','HISAR'],['KARNAL/KARNAL RO','KARNAL'],['ROHTAK CV','ROHTAK'],
    ['NARNAUL-HARIYANA','NARNAUL'],['NORTH EAST DELHI (GANAUR)','NORTH EAST DELHI'],['AMRITSAR - CDG','AMRITSAR'],
    ['BHATINDA - CDG','BHATINDA'],['FEROZEPUR-PUNJAB','FEROZEPUR'],['HOSHIARPUR - CDG','HOSHIARPUR'],['JALANDHAR - CDG','JALANDHAR'],
    ['LUDHIANA - CDG','LUDHIANA'],['MOGA - CHANDIGARH','MOGA'],['PATIALA - CDG','PATIALA'],['TARN TARAN','TARN TARAN']
  ];
  for(const [src,dst] of aliases){ if(k.includes(src)) return dst; }
  return k;
}
function landmarkFor(branch,state){
  const k=landmarkKey(branch);
  return landmarks[k] || landmarks[branch] || `Local heritage landmark of ${branch}`;
}
