function copyPublicAssets(){
  const pub = path.join(__dirname, '..', 'public');
  for (const file of ['logo.webp','apple-touch-icon.png','_headers','_redirects']) {
    const src = path.join(pub, file), dst = path.join(out, file);
    if (fs.existsSync(src)) fs.copyFileSync(src, dst);
  }
  const images = path.join(pub, 'images'), outImages = path.join(out, 'images');
  if (fs.existsSync(images)) {
    ensure(outImages);
    for (const file of fs.readdirSync(images)) {
      const src = path.join(images, file), dst = path.join(outImages, file);
      if (fs.statSync(src).isFile()) fs.copyFileSync(src, dst);
    }
  }
}
function write(rel, html){const f=path.join(out,rel); ensure(path.dirname(f)); fs.writeFileSync(f, html);}
function metaDescription(text){
  const clean=String(text).replace(/\s+/g,' ').trim();
  if(clean.length<=140) return clean;
  const cut=clean.slice(0,137).replace(/\s+\S*$/,'').replace(/[,:;\-\s]+$/,'');
  return cut+'.';
}
function breadcrumbSchema(items){
  if(!items || items.length<2) return null;
  return {"@type":"BreadcrumbList","itemListElement":items.map((b,i)=>({"@type":"ListItem","position":i+1,"name":b.name,"item":b.url}))};
}
function schemaScript(title, canonical, description, breadcrumbs=[], extras=[]){
  const graph=[
    {"@type":"Organization","@id":site+'#organization',"name":company,"url":site,"logo":{"@type":"ImageObject","url":site+'/logo.webp'},"telephone":"+91-"+phone,"email":email,"areaServed":states.map(name=>({"@type":"AdministrativeArea","name":name})),"sameAs":["https://www.facebook.com/CSSSERVICESOLUTION","https://www.youtube.com/@cssservicesolution5742","https://www.instagram.com/cssservicesolution/","https://www.linkedin.com/in/sanket-singh-331943439/","https://x.com/ServiceCss"],"hasMap":"https://www.google.com/maps/place/CSS+Service+Solution/@28.7987294,77.1358362,17z/data=!3m1!4b1!4m6!3m5!1s0x390d016131a4ff63:0x550f75934d0f9d4!8m2!3d28.7987294!4d77.1358362!16s%2Fg%2F11j2mt4dp4?entry=ttu&g_ep=EgoyMDI2MDkyOS4wIKXMDSoASAFQAw%3D%3D"},
    {"@type":"WebSite","@id":site+'#website',"url":site,"name":company,"publisher":{"@id":site+'#organization'}},
    {"@type":"WebPage","@id":canonical+'#webpage',"url":canonical,"name":title,"description":description,"isPartOf":{"@id":site+'#website'}}
  ];
  const crumb=breadcrumbSchema(breadcrumbs); if(crumb) graph.push(crumb);
  for(const extra of extras) graph.push(extra);
  return '<script type="application/ld+json">'+JSON.stringify({"@context":"https://schema.org","@graph":graph}).replace(/</g,'\\u003c')+'</script>';
}
function titleForShare(canonical){return canonical===site+'/' ? company : company+' | '+canonical.replace(site,'').replace(/\//g,' ').trim();}
function shareBar(canonical){
  const u=encodeURIComponent(canonical), t=encodeURIComponent(titleForShare(canonical)+' '+canonical);
  return `<div class="sharebar" aria-label="Share this page"><span>Share this page:</span><a class="share-link" href="https://www.facebook.com/sharer/sharer.php?u=${u}" target="_blank" rel="noopener noreferrer">Facebook</a><a class="share-link" href="https://www.linkedin.com/sharing/share-offsite/?url=${u}" target="_blank" rel="noopener noreferrer">LinkedIn</a><a class="share-link" href="https://wa.me/?text=${t}" target="_blank" rel="noopener noreferrer">WhatsApp</a></div>`;
}
