<section class="stats"><div class="wrap"><div class="stats-grid"><div class="stat"><strong>10</strong><span>Service categories</span></div><div class="stat"><strong>${totalLocations}+</strong><span>Listed location records</span></div><div class="stat"><strong>${states.length}</strong><span>States covered</span></div><div class="stat"><strong>1 Call</strong><span>For a service enquiry</span></div></div></div></section>
