write('contact/index.html',layout('Contact Complete Service Solution | Pest Control','Contact Complete Service Solution for pest control, termite treatment, fumigation and related service enquiries.',site+'/contact/',`<section class="section"><div class="wrap"><div class="crumb"><a href="/">Home</a> / Contact</div><h1>Contact Complete Service Solution</h1><p>Call, WhatsApp or email us with your city, service required and property type.</p><div class="actions"><a class="btn" href="tel:${phone}">Call ${phone}</a><a class="btn secondary" href="https://wa.me/${wa}">WhatsApp</a><a class="btn" href="mailto:${email}">Email Us</a></div><div class="quote-box"><h2>Get a Free Quote</h2><p>Tell us your city, service and property type. We will contact you with the next steps.</p><form class="form" id="enquiry-form" action="https://formsubmit.co/${email}" method="POST"><input type="hidden" name="_subject" value="New Pest Control Enquiry - Complete Service Solution"><input type="hidden" name="_template" value="table"><input type="hidden" name="_url" value="${site}/contact/"><input name="name" placeholder="Your name" autocomplete="name" required><input name="mobile" placeholder="Mobile number" inputmode="tel" autocomplete="tel" required><input name="city" placeholder="City" autocomplete="address-level2"><select name="service"><option value="">Select service</option>${services.map(s=>`<option value="${esc(s.name)}">${esc(s.name)}</option>`).join('')}</select><select name="property"><option value="">Property type</option><option>Residential</option><option>Commercial</option><option>Industrial</option><option>Other</option></select><input name="preferredDate" type="date" aria-label="Preferred date"><textarea name="message" placeholder="Tell us about your pest issue"></textarea><input name="website" tabindex="-1" autocomplete="off" style="position:absolute;left:-9999px" aria-hidden="true"><button class="btn quote-btn" type="submit">Send Enquiry</button><p id="enquiry-status" class="form-status" role="status" aria-live="polite"></p><p class="quote-note">Your enquiry is submitted securely online. You do not need to open Gmail or another email app.</p></form><script>(function(){const f=document.getElementById('enquiry-form'),s=document.getElementById('enquiry-status');if(!f)return;f.addEventListener('submit',async e=>{e.preventDefault();const b=f.querySelector('button');b.disabled=true;b.textContent='Sending…';s.textContent='Sending your enquiry…';s.className='form-status';try{const r=await fetch('https://formsubmit.co/ajax/${email}',{method:'POST',headers:{'Accept':'application/json'},body:new FormData(f)});const d=await r.json();if(!r.ok||d.success===false)throw new Error(d.message||'Unable to submit enquiry');f.reset();s.textContent='✓ Enquiry sent successfully. We will contact you shortly.';s.className='form-status success'}catch(err){s.textContent='Sorry, your enquiry could not be sent right now. Please call or WhatsApp us.';s.className='form-status error'}finally{b.disabled=false;b.textContent='Send Enquiry'}})})();</script><p><strong>Email:</strong> ${email}</p><p><strong>Coverage:</strong> Delhi, Uttar Pradesh, Haryana, Rajasthan and Punjab.</p></div></div></section>`,[{name:'Home',url:site+'/'},{name:'Contact',url:site+'/contact/'}]));
